using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace CorseVR.Editor {
public static class CouvertureV7 {
 const string A="Assets/Prototype_Maquis/Art/FinitionV7";
 public static string Add(){if(EditorApplication.isPlaying)throw new Exception("Edit required");var main=GameObject.Find("Maquis_35m").transform;var ext=GameObject.Find("Extension_Tour_Littoral").transform;var zones=ext.GetComponent<TourZoneSeparation>();var mainRoute=main.GetComponent<Maquis35Route>();var coast=ext.GetComponent<TourLittoralRoute>();var rng=new System.Random(78103);Func<float,float,float> random=(a,b)=>a+(float)rng.NextDouble()*(b-a);var material=AssetDatabase.LoadAssetAtPath<Material>(A+"/Materials/Botanique_Fibres_Nervures_V7.mat");int total=0,cells=0;
  for(int zone=0;zone<2;zone++){var owner=zone==0?main:ext;var name=zone==0?"13_Strate_Basse_Finition":"08_Strate_Basse_Finition";if(owner.Find(name))continue;zones.ApplySide(zone==0?TourZoneSeparation.Side.Maquis:TourZoneSeparation.Side.Littoral);Physics.SyncTransforms();var parent=new GameObject(name);parent.transform.SetParent(owner,false);var terrain=zone==0?main.Find("01_Terrain_Chemin").GetComponentInChildren<MeshCollider>():ext.Find("02_Terrain_Littoral/Sol_Chemin_Littoral").GetComponent<MeshCollider>();var placements=new Dictionary<int,List<Matrix4x4>>();
   for(float station=zone==0?1.1f:2.4f;station<(zone==0?33.0f:32.5f);station+=random(.30f,.57f))for(int side=-1;side<=1;side+=2)for(int row=0;row<2;row++){if(rng.NextDouble()<.18)continue;var centre=zone==0?mainRoute.WorldAt(station):coast.WorldAt(station);var direction=zone==0?mainRoute.Direction(station):coast.Direction(station);var normal=Vector3.Cross(Vector3.up,direction).normalized;var p=centre+normal*side*(random(.96f,1.22f)+row*random(.24f,.53f))+direction*random(-.2f,.2f);if(new Vector2(p.x-ext.position.x,p.z-ext.position.z).magnitude<4.9f)continue;var second=ext.Find("07_Seconde_Tour_Genoise");if(new Vector2(p.x-second.position.x,p.z-second.position.z).magnitude<4.9f)continue;RaycastHit hit;if(!terrain.Raycast(new Ray(p+Vector3.up*20,Vector3.down),out hit,50))continue;p=hit.point-Vector3.up*.035f;float height=random(zone==0?.27f:.18f,zone==0?.46f:.32f);var overlaps=Physics.OverlapSphere(p+Vector3.up*height*.45f,height*.52f,~0,QueryTriggerInteraction.Ignore);if(overlaps.Any(c=>c!=terrain&&!c.name.Contains("Sol_")&&!c.name.Contains("Falaises")&&!c.name.Contains("Terrain")&&!c.name.Contains("Enveloppe")))continue;
    var m=Matrix4x4.TRS(p,Quaternion.Euler(0,random(0,360),0),new Vector3(height/.4f*random(.85f,1.18f),height/.4f,height/.4f*random(.85f,1.18f)));int key=(int)(station/7);if(!placements.ContainsKey(key))placements[key]=new List<Matrix4x4>();placements[key].Add(m);total++;}
   var renderers=new List<Renderer>();foreach(var cell in placements){var go=new GameObject("Prairie_Discontinue_"+cell.Key);go.transform.SetParent(parent.transform,false);var lods=new List<LOD>();for(int level=1;level<=2;level++){var source=AssetDatabase.LoadAssetAtPath<GameObject>(A+"/Models/V7_Herbes_"+(cell.Key%2)+"_Niveau"+(level==1?0:2)+".fbx").GetComponentInChildren<MeshFilter>();var combine=cell.Value.Select(m=>new CombineInstance{mesh=source.sharedMesh,transform=parent.transform.worldToLocalMatrix*m*Matrix4x4.Scale(new Vector3(-1,1,1))*source.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh();mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.CombineMeshes(combine,true,true);mesh.RecalculateBounds();var assetPath=A+"/Meshes/Couverture_"+zone+"_"+cell.Key+"_"+level+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(assetPath);if(existing){EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,assetPath);var child=new GameObject("Distance_"+level);child.transform.SetParent(go.transform,false);child.AddComponent<MeshFilter>().sharedMesh=mesh;var r=child.AddComponent<MeshRenderer>();r.sharedMaterial=material;r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;renderers.Add(r);lods.Add(new LOD(level==1?.045f:.006f,new Renderer[]{r}));}var group=go.AddComponent<LODGroup>();group.SetLODs(lods.ToArray());group.RecalculateBounds();cells++;}
   if(zone==0){zones.maquisRenderers=zones.maquisRenderers.Concat(renderers).ToArray();zones.maquisInitial=zones.maquisInitial.Concat(renderers.Select(r=>true)).ToArray();}else{zones.littoralRenderers=zones.littoralRenderers.Concat(renderers).ToArray();zones.littoralInitial=zones.littoralInitial.Concat(renderers.Select(r=>true)).ToArray();}}
  zones.ApplySide(TourZoneSeparation.Side.Maquis);EditorUtility.SetDirty(zones);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());return total+" clumps combined into "+cells+" cells with two LODs";}
}
}
